  ".dk3-screen i:nth-child(4){width:72%;}",
  ".dk3-screen i:nth-child(5){width:54%;background:var(--dkan-code-a);}",
  // 人物组（坐在桌子中间近镜头侧 z=30，侧身面朝 +X 三屏；不会被桌体遮挡）
